{
  "status": "SUPPORTED",
  "task_summary": "Find fastening parts and tools in storage, assemble the fastening at the marked spot on the workbench, and return the tool to the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_location",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific area on the workbench where fastening is required.",
        "required_count": 1
      ,
        "binding_policy": "SHARED",
        "candidate_categories": ["marked_spot", "assembly_point"],
        "required_properties": ["surface", "needs_fastening"]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The hardware part (e.g., screw, bolt) needed to secure the fastening.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "nut", "clip"],
        "required_properties": ["fits_fastener", "secure_part"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastening (e.g., screwdriver, wrench).",
        "required_count": 1
      ,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "driver_bit"],
        "required_properties": ["operates_on_fastener", "held_by_robot"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the task occurs and reusable tools are returned.",
        "required_count": 1
      ,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk"],
        "required_properties": ["flat_surface", "holds_items"]
      },
      {
        "id": "storage_container",
        "entity_kind": "REGION",
        "function": "Enclosed space (drawer or cabinet) containing components or tools.",
        "required_count": 1
      ,
        "binding_policy": "SHARED",
        "candidate_categories": ["drawer", "cabinet", "cupboard"],
        "required_properties": ["enclosed", "contains_items", "openable"]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "relation": "compatible_component is suitable for fastening at fastening_location",
        "participant_roles": ["compatible_component", "fastening_location"]
      ,
        "required": true
      },
      {
        "id": "relation_2",
        "relation": "fastening_tool is used to operate on compatible_component",
        "participant_roles": ["fastening_tool", "compatible_component"]
      ,
        "required": true
      },
      {
        "id": "relation_3",
        "relation": "fastening_tool is placed on workbench after use",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
        "required": true
      },
      {
        "id": "relation_4",
        "relation": "compatible_component is found within storage_container",
        "participant_roles": ["compatible_component", "storage_container"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_1",
        "operation": "Identify and retrieve compatible_component from storage_container",
        "participant_roles": ["compatible_component", "storage_container"]
      ,
        "operation_count": 1
      },
      {
        "id": "op_2",
        "operation": "Perform fastening using fastening_tool on fastening_location",
        "participant_roles": ["fastening_tool", "fastening_location", "compatible_component"]
      ,
        "operation_count": 1
      },
      {
        "id": "op_3",
        "operation": "Place fastening_tool on workbench",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_location": [
        {
          "label": "Yellow/Blue object on black mat",
          "visual_description": "Rectangular yellow and blue object on a black mat on the table surface."
        }
      ],
      "compatible_component": [],
      "fastening_tool": [],
      "workbench": [
        {
          "label": "Wooden table",
          "visual_description": "Wooden table with drawers underneath."
        }
      ],
      "storage_container": []
    },
    "inspectable_regions": [
      {
        "id": "region_1",
        "label": "Left Drawer",
        "visual_description": "Closed blue drawer under the left side of the table.",
        "reason": "Closed structure with handle, likely contains small components."
      },
      {
        "id": "region_2",
        "label": "Right Drawer",
        "visual_description": "Closed blue drawer under the right side of the table.",
        "reason": "Closed structure with handle, likely contains small components."
      },
      {
        "id": "region_3",
        "label": "Tall Cabinet",
        "visual_description": "Tall dark grey cabinet standing behind the table.",
        "reason": "Closed structure with handle, likely contains larger tools or components."
      }
    ],
    "inspection_order": [
      "region_1",
      "region_2",
      "region_3"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
